format_code:
chip esp32

func max(a: int, b: int) -> int {
    if a > b {
        return a
    }
    return b
}

func min(a: int, b: int) -> int {
    if a < b {
        return a
    }
    return b
}

setup {
    var big: int = max(10, 20)
    var small: int = min(10, 20)
}

system_graph.mermaid:
flowchart LR
    u_setup["setup"]
    f_max("max()")
    f_min("min()")
    u_max("max()")
    u_min("min()")
    u_setup -->|call| f_max
    u_setup -->|call| f_min
